 button('view').onclick=()=>{showOriginal=!showOriginal;sync();};button('stop').onclick=stop;button('undo').onclick=()=>{const saved=history.pop();if(!saved)return;({base,strokes,corners,soft}=saved);invalidate();sync();};button('clear').onclick=()=>{remember();base=null;strokes=[];corners=[];invalidate();sync();};button('close-polygon').onclick=()=>{if(corners.length<3)return;try{remember();const k=Math.min(1,768/Math.max(image.width,image.height));base=Core.polygon(corners,Math.max(2,Math.round(image.width*k)),Math.max(2,Math.round(image.height*k)),uid());strokes=[];corners=[];invalidate();notify('Đã giữ phần trong đường khoanh. Xem sticker hoặc dùng bút sửa mép.');sync();}catch(e){notify(e.message);}};
